{
  "name": "{{name}}",
  "private": true,
  "workspaces": [
    "apps/*",
    "packages/*"
  ],
  "scripts": {
    "dev": "bun run --filter '*' dev",
    "build": "bun run --filter '*' build",
    "typecheck": "bun run --filter '*' typecheck"
  }
}

{
  "name": "@app/api",
  "private": true,
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "dev": "bun --watch src/server.ts",
    "build": "bun build src/server.ts --target bun --outdir dist",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "elysia": "latest",
    "@elysiajs/cors": "latest"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "latest"
  }
}

import { cors } from "@elysiajs/cors";
import { Elysia, t } from "elysia";

// The API. Its type is exported so the client (packages/client) is typed without codegen.
export const app = new Elysia()
  .use(cors())
  .get("/health", () => ({ ok: true }))
  .post("/greet", ({ body }) => ({ message: `Hello, ${body.name}!` }), { body: t.Object({ name: t.String() }) });

export type App = typeof app;

import { app } from "./index";

app.listen(Number(process.env.PORT ?? 3000));
console.log(`API en http://localhost:${app.server?.port}`);

import { treaty } from "@elysiajs/eden";

import type { App } from "@app/api";

/** Typed client for the API: `await api.greet.post({ name })`. */
export const api = treaty<App>(import.meta.env?.VITE_API_URL ?? "localhost:3000");
